const listingTrack=$('#listing-track'),listingCards=$$('.editorial-property',listingTrack),listingProgress=$('#listing-progress-bar');
function updateListingProgress(){if(!listingTrack)return;const max=Math.max(1,listingTrack.scrollWidth-listingTrack.clientWidth),ratio=Math.min(1,listingTrack.scrollLeft/max);listingProgress.style.width=`${Math.max(25,100/(listingCards.filter(card=>!card.hidden).length||1))}%`;listingProgress.style.transform=`translateX(${ratio*(100/(parseFloat(listingProgress.style.width)||25)-1)*100}%)`}
function scrollListings(direction){const card=listingCards.find(item=>!item.hidden);if(card)listingTrack.scrollBy({left:direction*(card.getBoundingClientRect().width+14),behavior:'smooth'})}
$('#listing-prev')?.addEventListener('click',()=>scrollListings(-1));
$('#listing-next')?.addEventListener('click',()=>scrollListings(1));
listingTrack?.addEventListener('scroll',updateListingProgress,{passive:true});
addEventListener('resize',updateListingProgress,{passive:true});updateListingProgress();

let propertyMap,propertyMarkers=[];
function selectMapProperty(index,move=true){const item=propertyData[index],card=$('#map-property-card');if(!item||!card)return;card.classList.add('is-changing');setTimeout(()=>{$('#map-card-image').src=item.image;$('#map-card-image').alt=item.alt;$('#map-card-city').textContent=item.city;$('#map-card-title').textContent=item.title;$('#map-card-price').textContent=item.price;$('#map-card-facts').textContent=item.facts;$('#map-card-link').href=item.url;$$('[data-map-index]').forEach((button,i)=>button.classList.toggle('active',i===index));propertyMarkers.forEach((marker,i)=>marker.getElement()?.classList.toggle('is-active',i===index));card.classList.remove('is-changing')},150);if(move&&propertyMap)propertyMap.flyTo([item.lat,item.lng],index===3?12:13,{duration:1.1})}
if($('#property-map')&&window.L){propertyMap=L.map('property-map',{scrollWheelZoom:false,zoomControl:true}).setView([45.65,-73.3],9);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(propertyMap);propertyMarkers=propertyData.map((item,index)=>{const icon=L.divIcon({className:'',html:`<span class="property-number-marker">${index+1}</span>`,iconSize:[46,46],iconAnchor:[23,23]});const marker=L.marker([item.lat,item.lng],{icon,title:item.title}).addTo(propertyMap);marker.on('click',()=>selectMapProperty(index));return marker});setTimeout(()=>selectMapProperty(0,true),300)}else if($('#property-map')){$('#property-map').innerHTML='<p class="map-fallback">La carte interactive est momentanément indisponible. Les quatre propriétés restent accessibles ci-dessus.</p>'}
$$('[data-map-index]').forEach(button=>button.addEventListener('click',()=>selectMapProperty(Number(button.dataset.mapIndex))));
